/** Every persisted event; `type` is the discriminant. */
export type RunEvent =
  | RunCreated
  | RunStateChanged
  | RunPowerDetected
  | RunPowerCalibrationStarted
  | RunPowerCalibrationCompleted
  | RunCloneStarted
  | RunCloneCompleted
  | RunEnvStarted
  | RunEnvCompleted
  | RunDiscoveryStarted
  | RunDiscoveryCompleted
  | RunTriageStarted
  | RunTriageCompleted
  | RunSelectionConfirmed
  | RunArtifactsStarted
  | RunArtifactsCompleted
  | RunCompleted
  | RunFailed
  | RunCancelled
  | RunInterrupted
  | FunctionStarted
  | FunctionTestsWriteStarted
  | FunctionTestsWriteCompleted
  | FunctionTestsRunStarted
  | FunctionTestsRunCompleted
  | FunctionCaptureStarted
  | FunctionCaptureCompleted
  | FunctionBaselineStarted
  | FunctionBaselineCompleted
  | FunctionDecision
  | FunctionMergeStarted
  | FunctionMergeCompleted
  | FunctionCompleted
  | CandidateWriteStarted
  | CandidateWriteCompleted
  | CandidateCheckStarted
  | CandidateCheckCompleted
  | CandidateRejected
  | CandidateBenchQueued
  | CandidateBenchStarted
  | CandidateBenchCompleted
  | LlmUsage
  | Log

export type EventType = RunEvent['type']

export type EventOf<T extends EventType> = Extract<RunEvent, { type: T }>

export type RunState = RunStateChangedData['to_state']
export type RunMode = RunCreatedData['mode']
export type CandidateId = RankingEntry['candidate_id']
export type DecisionOutcome = FunctionDecisionData['outcome']
export type FunctionOutcome = FunctionCompletedData['outcome']
export type RejectReason = CandidateRejectedData['reason']
export type LlmStage = LlmUsageData['stage']
export type LogLevel = LogData['level']
export type LogSource = LogData['source']
